<script setup>
import {ref,reactive,computed,watch,nextTick} from 'vue';
import {FOOD_GROUPS,FOOD_BY_ID,searchFoods,GROUP_ICONS} from '../data/catalogue.js';
import {todayDate,MEALS,normalizeEntries,makeRecord,analysisVersion} from '../lib/foodNutrition.js';
import {useLocalNutrition} from '../composables/useLocalNutrition.js';
import {useAiReports} from '../composables/useAiReports';
import PortionPicker from '../components/PortionPicker.vue';
import {createNutritionSnapshot} from '../lib/nutritionSnapshot.js';
import {foodTitle} from '../lib/foodPresentation.js';
import AppIcon from '../components/AppIcon.vue';
import PhotoRecognitionPanel from '../components/PhotoRecognitionPanel.vue';
import NutrientSummary from '../components/NutrientSummary.vue';
const props=defineProps({records:Array,reports:{type:Array,default:()=>[]},profile:Object,nutrition:Object,initialDate:String,saving:Boolean});
const emit=defineEmits(['save','remove','analysis','browse','detail']);const{state,ensureDraft,addToDraft}=useLocalNutrition();const{isStale}=useAiReports();
const openGroups=reactive({}),groupLimits=reactive({});
const date=ref(props.initialDate||todayDate()),query=ref(''),meal=ref('unspecified'),activeAsideTab=ref('selected'),asidePanel=ref(null),error=ref('');
watch(()=>props.initialDate,value=>{if(value)date.value=value;});watch(date,value=>{ensureDraft(value);error.value='';query.value='';},{immediate:true});
const draft=computed(()=>state.drafts[date.value]);const selected=computed(()=>normalizeEntries(draft.value?.entries));const matches=computed(()=>searchFoods(query.value,8));
const savedRecord=computed(()=>props.records.find(item=>item.date===date.value));
const latestFor=value=>props.reports.find(report=>report.date===value);
const pendingSame=computed(()=>{const report=latestFor(date.value);return report?.status==='pending'&&report.dataVersion===analysisVersion(makeRecord(draft.value),props.profile);});
function addFood(food){addToDraft({date:date.value,foodId:food.key,grams:food.grams||100,meal:meal.value});query.value='';activeAsideTab.value='selected';}
function addManual(){draft.value.entries.push({id:crypto.randomUUID(),foodId:null,name:query.value.trim(),grams:100,meal:meal.value,group:'snacks',source:'manual',referenceConfirmed:true});query.value='';}
function confirmPhoto({items,batchId}){if(draft.value.appliedBatches.includes(batchId))return;const entries=normalizeEntries(items.map(item=>({...item,id:crypto.randomUUID(),meal:meal.value,source:'photo',estimated:true,referenceConfirmed:true,nutritionSnapshot:createNutritionSnapshot(FOOD_BY_ID[item.foodId])})));if(entries.length!==items.length){error.value='请核对每项食物名称与克数。';return;}draft.value.entries.push(...entries);draft.value.appliedBatches.push(batchId);draft.value.recognition.confirmed=true;activeAsideTab.value='selected';}
function save(){if(props.saving)return;error.value='';if(selected.value.length!==draft.value.entries.length){error.value='请填写每项食物名称，并将克数设为 0.1–5000 克；不需要的项目可删除。';return;}emit('save',JSON.parse(JSON.stringify(draft.value)));}
function switchTab(tab){activeAsideTab.value=tab;if(matchMedia('(max-width:950px)').matches)nextTick(()=>asidePanel.value?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'start'}));}
function tabKeys(event){const tab=['ArrowRight','ArrowDown','End'].includes(event.key)?'history':['ArrowLeft','ArrowUp','Home'].includes(event.key)?'selected':null;if(tab){event.preventDefault();switchTab(tab);nextTick(()=>document.getElementById('vb-tab-'+tab)?.focus());}}
function reportLabel(record){const report=latestFor(record.date);if(!report)return'查看 AI 分析';if(isStale(report,record,props.profile))return'报告需更新';return report.status==='pending'?'分析中':report.status==='complete'?'查看 AI 分析':'分析未完成';}
</script>
<template><div class="vb-diary-page"><div class="vb-page-title"><div><p class="vb-eyebrow">一餐一记，慢慢更了解自己</p><h1>饮食记录</h1><p>填写可食部克数，核对食物，再保存这一天。</p></div><label class="vb-date-input"><AppIcon name="calendar" :size="18" /><input v-model="date" type="date" :max="todayDate()" aria-label="饮食记录日期" /></label></div><div v-if="draft" class="vb-diary-grid"><aside class="vb-diary-aside" aria-label="记录摘要和最近记录"><PhotoRecognitionPanel :key="date" :draft="draft" :legacy-photo="savedRecord?.photo" @confirm="confirmPhoto" /><div class="vb-diary-tabs" role="tablist" aria-label="饮食记录摘要" @keydown="tabKeys"><button v-for="[key,label,count] in [['selected','本次选择',selected.length],['history','最近记录',records.length]]" :id="'vb-tab-'+key" :key="key" type="button" role="tab" :aria-selected="activeAsideTab===key" :aria-controls="'vb-panel-'+key" :tabindex="activeAsideTab===key?0:-1" :class="{selected:activeAsideTab===key}" @click="switchTab(key)">{{ label }}<span>{{ count }}</span></button></div><section v-if="activeAsideTab==='selected'" id="vb-panel-selected" ref="asidePanel" class="vb-glass vb-aside-panel vb-selected-panel" role="tabpanel" aria-labelledby="vb-tab-selected" tabindex="0"><div class="vb-section-heading"><div><h2>本次选择</h2><p>{{ date }}</p></div><span class="vb-pill">{{ selected.length }} 项</span></div><NutrientSummary :entries="selected" compact /><div v-if="selected.length" class="vb-selected-list"><div v-for="entry in selected" :key="entry.id"><span>{{ entry.name }}<small>{{ MEALS.find(([id])=>id===entry.meal)?.[1] }}{{ entry.estimated?' · 估重':'' }}</small></span><strong>{{ entry.grams }}<small> g</small></strong></div></div><p v-else class="vb-muted-empty">选择食物后，会在这里汇总。</p></section><section v-else id="vb-panel-history" ref="asidePanel" class="vb-glass vb-aside-panel vb-history-panel" role="tabpanel" aria-labelledby="vb-tab-history" tabindex="0"><div class="vb-section-heading"><div><h2>最近记录</h2><p>打开记录或查看历史分析</p></div><AppIcon name="calendar" :size="18" /></div><div v-if="records.length" class="vb-history-list"><div v-for="record in records.slice(0,12)" :key="record.date" class="vb-history-item vb-history-with-ai"><button type="button" :aria-label="`打开 ${record.date} 的饮食记录`" @click="date=record.date"><span class="vb-status-dot" /><span><strong>{{ record.date }}</strong><small>{{ Object.values(record.foods||{}).filter(value=>Number(value)>0).length }} 类食物</small></span></button><button type="button" class="vb-history-analysis" @click="$emit('analysis',record.date)">{{ reportLabel(record) }}</button><button type="button" class="vb-icon-button" :aria-label="'删除'+record.date+'的记录'" @click="$emit('remove',record.date)"><AppIcon name="close" :size="14" /></button></div></div><p v-else class="vb-muted-empty">你的第一天记录，从今天开始。</p></section><div class="vb-diary-actions"><p><AppIcon name="lock" :size="14" />保存后可查看分析，AI分析由你主动开始。</p><button type="submit" form="vb-diary-form" class="vb-button vb-button-primary vb-save-record" :disabled="saving">{{ saving?'正在保存…':'保存记录' }}<AppIcon name="arrow" :size="17" /></button><button v-if="savedRecord" type="button" class="vb-button vb-button-soft" @click="$emit('analysis',date)">查看分析</button><p v-if="error" class="vb-feature-error" role="alert">{{ error }}</p></div></aside>
 <form id="vb-diary-form" class="vb-glass vb-diary-form" @submit.prevent="save"><div class="vb-section-heading"><div><h2>这一天，吃了什么？</h2><p>条目会保留在本地草稿，保存后进入最近记录。</p></div><button type="button" class="vb-text-button" @click="$emit('browse')">食物浏览 →</button></div><div class="vb-diary-search-row"><label class="vb-search-field"><AppIcon name="search" :size="18" /><input v-model="query" type="search" aria-label="搜索记录食物" placeholder="搜索同一食物库，如香蕉、西红柿" @keydown.enter.prevent="matches[0]&&addFood(matches[0])" /></label><label class="vb-meal-select"><span>添加到</span><select v-model="meal" aria-label="添加食物的餐次"><option v-for="[id,label] in MEALS" :key="id" :value="id">{{ label }}</option></select></label></div><div v-if="query.trim()" class="vb-search-results"><button v-for="food in matches" :key="food.key" type="button" class="vb-search-result" @click="addFood(food)"><span><strong>{{ food.name }}</strong><small>{{ food.state }} · {{ food.source?'数据库样本':'暂无成分数据' }}</small></span><AppIcon name="plus" :size="17" /></button><p v-if="!matches.length" class="vb-search-empty">没有匹配项，可以手动录入；缺失营养数据不会当作 0。</p><button class="vb-add-custom-button" type="button" @click="addManual">手动添加“{{ query }}”<AppIcon name="plus" :size="16" /></button></div>
 <div class="vb-diary-entry-heading"><h3>已选食物 <small>{{ draft.entries.length }} 项</small></h3><button type="button" class="vb-text-button" @click="addManual">＋手动添加</button></div><div v-if="draft.entries.length" class="vb-diary-entries"><article v-for="(entry,index) in draft.entries" :key="entry.id" class="vb-diary-entry"><div class="vb-diary-entry-title"><button v-if="entry.foodId" type="button" class="vb-entry-name" @click="$emit('detail',entry.foodId)">{{ foodTitle(FOOD_BY_ID[entry.foodId])||entry.name }}<AppIcon name="chevron" :size="13" /></button><input v-else v-model="entry.name" :aria-label="'手动食物'+(index+1)+'名称'" placeholder="填写食物名称" maxlength="100" required /><button type="button" class="vb-icon-button" :aria-label="'移除食物'+(index+1)" @click="draft.entries.splice(index,1)"><AppIcon name="close" :size="15" /></button></div><p class="vb-data-note">{{ entry.foodId?FOOD_BY_ID[entry.foodId]?.state:'手动条目，暂无营养数据' }}{{ entry.estimated?' · 份量为估算':'' }}<span v-if="entry.nutritionSnapshot?.dataType==='ai-estimate'" class="vb-pill">含AI估算</span></p><PortionPicker :food="FOOD_BY_ID[entry.foodId]" @choose="entry.grams=$event;entry.estimated=true" /><div class="vb-entry-controls"><label>可食部重量<input v-model="entry.grams" type="number" min="0.1" max="5000" step="0.1" required :aria-label="(FOOD_BY_ID[entry.foodId]?.name||entry.name||'食物')+'克数'" /><small>克</small></label><label>餐次<select v-model="entry.meal"><option v-for="[id,label] in MEALS" :key="id" :value="id">{{ label }}</option></select></label><label v-if="!entry.foodId">归属类别<select v-model="entry.group"><option v-for="group in FOOD_GROUPS" :key="group.key" :value="group.key">{{ group.name }}</option></select></label></div><p v-if="entry.referenceConfirmed===false" class="vb-inline-warning">这是历史记录，具体数据库样本尚未确认，不计入营养小计。<button v-if="FOOD_BY_ID[entry.foodId]?.source" type="button" class="vb-text-button" @click="entry.referenceConfirmed=true">核对后使用此参考样本</button><button v-else type="button" class="vb-text-button" @click="$emit('browse')">查找具体食物</button></p></article></div><p v-else class="vb-muted-empty">从搜索或下方类别中选择食物，也可以拍照后确认添加。</p><details v-for="group in FOOD_GROUPS" :key="group.key" class="vb-diary-food-group" @toggle="openGroups[group.key]=$event.target.open"><summary><AppIcon :name="GROUP_ICONS[group.key]" :size="18" />{{ group.name }}<small>{{ group.items.length }} 个条目</small><AppIcon name="chevron" :size="14" /></summary><div v-if="openGroups[group.key]"><button v-for="[id,name] in group.items.slice(0,groupLimits[group.key]||24)" :key="id" type="button" @click="addFood(FOOD_BY_ID[id])">{{ name }} ＋</button><button v-if="group.items.length>(groupLimits[group.key]||24)" type="button" @click="groupLimits[group.key]=(groupLimits[group.key]||24)+24">再显示24项</button></div></details><label class="vb-field vb-notes-field">补充备注 <span>可选，不发送给 AI</span><textarea v-model="draft.notes" rows="3" maxlength="240" placeholder="记录做法、口味或当天的感受…" /></label><details class="vb-intake-more"><summary>查看记录依据</summary><p>保存所选样本或AI估算快照，未知值不补0。旧记录未保存快照时仍依据原目录计算。</p><p v-for="entry in selected" :key="entry.id">{{ entry.name }}：{{ entry.nutritionSnapshot?.source?.name||entry.nutritionSnapshot?.estimate?.model||'原目录数据' }}<span v-if="entry.nutritionSnapshot?.estimate"> · {{ entry.nutritionSnapshot.estimate.assumption }}</span></p></details></form></div></div></template>
